; beat.asm -- chapter 20: a pair of bytes at every T-state of a line
; generated by gen20.py
        INCLUDE "msx.inc"
        OUTPUT "beat.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
BOX_EMPTY EQU 1             ; the library's two boxes, characters 1 and 2
BOX_FULL  EQU 2
; 228 pairs of bytes, the filled box and then the empty one 20 T-states after,
; 115 T-states apart: the first pair's first byte at T-state 0 of the paper's
; line 3, the others at every other T-state of a line once. Each pair goes to
; two cells of the name table: the pair made at T-state p, to cells 2p and 2p + 1.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, t1
        call puts
        ld b, 18
        ld c, 0
        ld hl, t2
        call puts
        ld b, 19
        ld c, 0
        ld hl, t3
        call puts
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, wj         ; 11
w5s:    ld de, 932
w5:     dec de
        ld a, d
        or e
        jr nz, w5
        ld c, 0
        nop
        nop
        nop
        nop
        nop
        jp wg             ; 11
wj:
w6s:    ld de, 544
w6:     dec de
        ld a, d
        or e
        jr nz, w6
        ld c, 0
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
        nop
        nop
        nop
wg:
        ld hl, cells            ; 11
        ld b, 228               ;  8
        ld c, VDP_DATA          ;  8
        ld d, BOX_FULL          ;  8: the first byte
bt:     ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12
        inc hl                  ;  7
        ld a, (hl)              ;  8
        out (VDP_CTRL), a       ; 12: the pair's two cells
        inc hl                  ;  7
        ld a, BOX_EMPTY         ;  8: the second byte
b1:     out (c), d              ; 14: the first, written 10 T-states in
        ld e, 0                 ;  8
b2:     out (VDP_DATA), a       ; 12: the second, written 8 in: 20 after the first
        nop                     ;  5
        djnz bt                 ; 14: 115 a pair
done:   jr done

; isr: the frame's interrupt, taken once, to start in step with the picture
isr:    push af
        in a, (VDP_CTRL)        ; the status: the VDP takes its signal down
        pop af
        ei
        ret
t1:        db "PAIRS OF BYTES, 20 T APART:", 0
t2:        db 2, 1, " BOTH ARRIVED", 0
t3:        db 1, "  THE FIRST WAS LOST", 0
